def compute(vars):
    total_shares = vars["v1"]
    average_price_per_share = vars["v2"]
    total_cost = total_shares * average_price_per_share

    return {
        "value": total_cost,
        "trace": {
            "total_shares": total_shares,
            "average_price_per_share": average_price_per_share,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
